import time
from neo4j import driver

def unit_of_work(metadata=None, timeout=None):
    start_time = time.time()

    def decorator(func):
        def wrapper(*args, **kwargs):
            nonlocal start_time
            with driver.driver('bolt://localhost:7687') as driver:
                session = driver.session()
                try:
                    if metadata:
                        session.write_transaction(unit_of_work._set_metadata, metadata)
                    if timeout:
                        session.config['transaction.timeout'] = timeout
                    result = session.run(func.__name__, *args, **kwargs)
                    record = result.single()
                    end_time = time.time()
                    print(f"Transaction {func.__name__} completed in {end_time - start_time:.4f} seconds")
                except Exception as e:
                    session.close()
                    exception_handler(e)
        return wrapper
    return decorator

def exception_handler(exception):
    # Handle the exception, e.g., log the error
    print(f"An error occurred: {exception}")

