import numpy as np

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""
    class Point(np.ndarray):
        _shape_tuple = ()

        @classmethod
        def __new__(cls, *args, **kwargs):
            # Use the provided fields to determine the dtype
            dtype = np.dtype([(field, np.float64) for field in fields])
            return super().__new__(cls, args, dtype=dtype, **kwargs)

        def __str__(self):
            return f"Point({', '.join([f'{name}_{i+1}' for i in range(len(self))])})"

        def _get_srid_code(self):
            """ Retrieve the SRID code based on the SRID maps"""
            return srid_map.get(self[0], -1)

        def __getitem__(self, item):
            extension = item % len(fields)
            return f"{name}_{extension + 1}"

        def __setitem__(self, item, value):
            extension = item % len(fields)
            self[extension] = value

    return Point

