from functools import wraps
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    cache = {}
    last_accessed = {}

    @wraps(func)
    def memoized_func(*args, **kwargs):
        key = (args, frozenset(kwargs.items())) if typed else args

        if key in cache:
            # Check if the item is still within its TTL
            if timer() - last_accessed[key] < ttl:
                return cache[key]

        result = func(*args, **kwargs)
        cache[key] = result
        last_accessed[key] = timer()

        if len(cache) > maxsize:
            key_to_remove = min(last_accessed, key=last_accessed.get)
            del cache[key_to_remove]
            del last_accessed[key_to_remove]

        return result

    return memoized_func

