class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.cache = {}
        self.usage = {}
        self.maxsize = maxsize

    def get(self, key):
        value, usage = self.cache.get(key, (None, 0))
        if usage < self.usage[key]:
            self.usage[key] = usage + 1
        elif len(self.cache) > self.maxsize:
            _, _ = self.popitem(False)
        return value

    def set(self, key, value):
        if value is None:
            return
        if key in self.cache:
            self.pop(key)
        self.usage.setdefault(key, 1)
        self.cache[key] = value

    def popitem(self, last=True):
        _, key = next(iter(self.usage.items()), (None, None))
        del self.usage[key]
        del self.cache[key]
        if last:
            self.cache.popitem(last=False)

