class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        if not isinstance(e, Exception):
            raise ValueError("Input must be an exception instance")

        def format_callable(obj, level, path_level):
            call_path = '.'.join([cls.extostr(e, max_level - 1, max_path_level - 1) for e in obj.__call__.f_code.co_stack[:level + 1]])
            return f"{obj.__class__.__name__}({call_path})"

        def format_exception(e, level, path_level):
            if level >= max_level:
                return f"... {e}"
            if path_level >= max_path_level:
                return f"{e}"

            formatted_exc = ""
            if len(e.args) > 0:
                formatted_exc += f" args: {e.args}"
            formatted_exc += f" | {format_exception(e, level - 1, path_level + 1)}"

            return formatted_exc

        return format_exception(e, max_level - 1, max_path_level - 1)

