        missing_in_fixity = unique_files_in_manifest - unique_files_in_fixity
        additional_in_fixity = unique_files_in_fixity - unique_files_in_manifest

        if missing_in_fixity:
            print(f"Fixity block contains files that are not listed in the manifest: {missing_in_fixity}")

        if additional_in_fixity:
            print(f"Fixity block references files that are not listed in the manifest: {additional_in_fixity}")

