import os
import hashlib

class InventoryManager:
    def validate_version_inventories(self, version_dirs):
        if version_dirs is None or len(version_dirs) <= 1:
            return True  # No need to validate if there's only one or less versions

        root_inventory_path = os.path.join(version_dirs[0], '..')
        root_inventory_hash = self.calculate_inventory_hash(root_inventory_path)

        all_inventory hashes = []
        for version_dir in version_dirs:
            version_inventory_path = os.path.join(version_dir, 'inventory')
            version_inventory_hash = self.calculate_inventory_hash(version_inventory_path)
            all_inventory_hashes.append((version_dir, version_inventory_hash))

        for version_dir, version_hash in all_inventory_hashes:
            if version_hash != root_inventory_hash:
                return False  # Found a content digest that does not match

        return True

    def calculate_inventory_hash(self, inventory_path):
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory not found at {inventory_path}")

        with open(inventory_path, 'rb') as file:
            inventory_data = file.read()

        hash_obj = hashlib.md5(inventory_data).hexdigest()
        return hash_obj

