import re

def size_to_bytes(size: str) -> int:
    # Extract numerical part and unit from the input string
    match = re.search(r"(\d+(\.\d+)?)(.*)", size)
    if not match:
        raise ValueError("Invalid input format")

    num_part = float(match.group(1))
    unit = match.group(2).strip().upper()

    # Convert the numerical part to bytes with a factor based on the unit
    if unit == "K":
        return int(num_part * 1024)
    elif unit == "M":
        return int(num_part * 1024**2)
    elif unit == "G":
        return int(num_part * 1024**3)
    elif unit == "T":
        return int(num_part * 1024**4)
    else:
        raise ValueError("Unsupported unit")

