import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        if re.match(r'^[_a-zA-Z][a-zA-Z0-9]*$', s):
            return [s]
        else:
            result = []
            for word in re.split(r'[\s]+', s):
                if re.match(r'^[_a-zA-Z][a-zA-Z0-9]*$', word):
                    result.append(word)
                else:
                    result.extend(word.split())
            return result
    elif platform == 1:
        # POSIX-specific split logic
        return s.split()
    elif platform == 0:
        # Windows-specific split logic (cmd.exe)
        return re.split(r'[\s]+', s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1, or 0.")

