def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True  # Skip the claim check if tentative
    if not iface.providedBy(candidate):
        raise Invalid("Candidate does not claim to provide the interface")

    for name, method in candidate.__dict__.items():
        if callable(method):
            signature = inspect.signature(method)
            required_by_iface = iface.getAllProvidedBy()
            if not signature.containsNoneOf(required_by_iface):
                raise Invalid(f"Method '{name}' does not provide all required-by iface.")
