def verifyObject(iface, candidate, tentative=False):
    '''
    Verify that `candidate` might correctly provide `iface`.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    '''

    errors = []

    def check_method(method_name):
        method = getattr(candidate, method_name, None)
        if method is None:
            errors.append(f"Missing method: {method_name}")
            return False

        sig = method.__signature__()
        if sig is None:
            errors.append(f"Invalid method signature: {method_name}")
            return False

        for required, _, _ in sig.parameters.values():
            if required:
                attr_name = f"{method_name}_{required.argname}"
                if not hasattr(candidate, attr_name):
                    errors.append(f"Missing attribute: {attr_name}")
                    return False

        return True

    for required_method in iface.__required_methods__:
        if not check_method(required_method):
            return False

    for attribute in iface.__required_attributes__:
        if not hasattr(candidate, attribute):
            errors.append(f"Missing attribute: {attribute}")

    if tentative:
        return True

    Raises = []
    for error in errors:
        if raises:
            raises.append(f"Multiple errors: {error}")
        else:
            raises.append(error)

    if raises:
        raise Invalid(raises)
    else:
        return True

