from typing import Tuple, Set, Callable, Union

def find_tags(text: str, replacer: Callable[[str], Union[str, None]] = None) -> Tuple[Set, str]:
    raw_tags = re.findall(r"<\w+>", text, re.IGNORECASE)
    escaped_tags = set()
    unmatched_markup = []

    for match in raw_tags:
        if any((C in match for C in ("{{", "}}"))):
            unmatched_markup.append(match)
        else:
            escaped_tags.add(match)

    text_out = text
    for tag in escaped_tags:
        match = re.search(rf"<{tag}>", text_out)
        if match:
            text_out = text_out[:match.start()] + (replacer(tag) or tag) + text_out[match.end():]

    return escaped_tags, text_out

