def verify_relayable_signature(public_key, doc, signature):
    import xml.etree.ElementTree as ET
    from cryptography.hazmat.primitives.asymmetric import padding, rsa
    from cryptography.hazmat.primitives import hashes
    from cryptography.exceptions import InvalidSignature

    root = ET.fromstring(doc)
    if signature:
        doc_signature = root.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
        if doc_signature is not None:
            # Extract the signature element
            sig_elem = doc_signature.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
            if sig_elem is not None:
                # Extract the computed signature from the document
                computed_signature = doc_signature.find('.//{http://www.w3.org/2000/09/xmldsig#} envelopedSignature').find('.//{http://www.w3.org/2001/04/xmldsig#}Text')
                if computed_signature is not None:
                    # Decode and confirm the signature
                    if computed_signature text == sig_elem.text:
                        print("Signature is valid.")
                    else:
                        print("Signature is invalid.")
                else:
                    print("Signature envelope not found.")
            else:
                print("Signature value not found.")
        else:
            print("No signature found.")
    else:
        print("No signature provided.")

