from collections import defaultdict

def _get_conditionally_required_args(self, command_name: str, options_spec: List, args: dict) -> List[str]:
    required_when_args = defaultdict(list)
    for option in options_spec:
        if option.get('required_when'):
            script_name = option.get('required_when').get('script')
            if script_name in args:
                required_when_args[script_name].append(option.get('option_name'))
    return [arg for script, args in required_when_args.items() for arg in args]

