def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not args:
        return False

    min_value = self.config.get('min_value')
    max_value = self.config.get('max_value')

    if not min_value or not max_value:
        return False

    if len(args) != 1:
        return False

    arg = args[0]

    if not isinstance(arg, (int, float)):
        return False

    if arg < min_value or arg > max_value:
        return False

    return True

