import os
from collections import defaultdict
import yaml

def get_plugin_spec_flatten_dict(plugin_dir):
    spec_files = [f for f in os.listdir(plugin_dir) if f.lower().endswith('.yaml')]
    flattened_dict = defaultdict(dict)

    for spec_file in spec_files:
        file_path = os.path.join(plugin_dir, spec_file)
        with open(file_path, 'r') as file:
            spec = yaml.safe_load(file)

            if 'properties' in spec:
                for key, value in spec['properties'].items():
                    flattened_dict[key] = value
            else:
                for key, value in spec.items():
                    if isinstance(value, dict):
                        flattened_dict[key].update(get_plugin_spec_flatten_dict(value))
                    else:
                        flattened_dict[key] = value

    return dict(flattened_dict)

